export default async function(app){const c=app.config;const ids=['fleet-kpis','stream-health','fleet-breakdown','vehicle-roster'];const mounts=Object.fromEntries(ids.map(id=>[id,app.getMount(id)]));const el=(tag,text,p)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;p?.append(n);return n;};const surface=n=>Object.assign(n.style,{minWidth:'0',boxSizing:'border-box',background:'#F8F2E7',color:'#3A3128',fontSize:'13px',border:'1px solid #E0D2BA',borderRadius:'7px',padding:'10px',boxShadow:'0 1px 3px #3A31280A'});Object.values(mounts).forEach(n=>{n.replaceChildren();surface(n);});const typeColor=t=>t==='Snow Plow'?c.snow:t==='Pickup'?c.pickup:c.grey;const grid=el('div',undefined,mounts['fleet-kpis']);Object.assign(grid.style,{display:'grid',gridTemplateColumns:'repeat(4,minmax(0,1fr))',gap:'10px',width:'100%',minWidth:'0'});const values={};for(const [key,label,note]of [['vehicles','Vehicles','Latest observations'],['moving','Moving','Fresh · speed > 0'],['speed','Average speed','Source units'],['observations','Observations','Retained history']]){const box=el('div',undefined,grid);Object.assign(box.style,{minWidth:'0',padding:'5px',borderLeft:'1px solid #E0D2BA'});el('div',label,box);values[key]=el('strong','—',box);Object.assign(values[key].style,{fontSize:'24px',display:'block'});const sub=el('small',note,box);sub.style.color='#8A7C69';}
const status=el('strong','Connecting…',mounts['stream-health']);status.setAttribute('role','status');const receipt=el('p','Waiting for live updates',mounts['stream-health']);const freshness=el('small','',mounts['stream-health']);freshness.style.color='#8A7C69';const types=el('div',undefined,mounts['fleet-breakdown']);const activity=el('div',undefined,mounts['fleet-breakdown']);activity.style.marginTop='12px';el('p','Received updates · last 60s',mounts['fleet-breakdown']);const spark=el('div',undefined,mounts['fleet-breakdown']);Object.assign(spark.style,{display:'flex',gap:'2px',alignItems:'end',height:'40px'});const sparkBars=Array.from({length:30},()=>{const b=el('div',undefined,spark);Object.assign(b.style,{flex:'1',minWidth:'0',background:c.grey,height:'1px'});return b;});const list=el('div',undefined,mounts['vehicle-roster']);const detail=el('div','Select a vehicle for details.',mounts['vehicle-roster']);Object.assign(detail.style,{marginTop:'10px',paddingTop:'10px',borderTop:'1px solid #E0D2BA',lineHeight:'1.6'});const note=el('p','Refresh 2s · stale after 30s. Up to 100 observations per vehicle. History resets on reopen. Speed units unspecified.',mounts['vehicle-roster']);Object.assign(note.style,{fontSize:'11px',color:'#8A7C69'});let disposed=false,busy=false,timer,handle,source,lv,rows=[],selected,received=0,times=[],lastReceipt=0,lastResult;const started=Date.now();const abort=new AbortController();app.onCleanup(()=>{disposed=true;clearInterval(timer);handle?.remove();abort.abort();Object.values(mounts).forEach(n=>n.replaceChildren());});const age=f=>{const t=Number(f.attributes.time);return Number.isFinite(t)?Math.max(0,(Date.now()-t)/1000):Infinity;};
function details(){const f=rows.find(f=>f.attributes.vehiclename===selected);detail.replaceChildren();if(!f){detail.textContent=selected?'Waiting for this vehicle.':'Select a vehicle for details.';return;}const a=f.attributes;el('strong',a.vehiclename,detail);for(const t of [`${a.vehicletype} · Agency ${a.agency}`,`Speed ${a.speed??'—'} · Heading ${a.heading??'—'}°`,`Observed ${new Date(a.time).toLocaleString()}`,`Observation age ${Math.round(age(f))}s`])el('div',t,detail);}
async function choose(input){selected=input?.graphic?.attributes?.vehiclename??input?.name;details();renderList();const f=rows.find(f=>f.attributes.vehiclename===selected);if(input?.zoom&&f?.geometry)await app.view.goTo({target:f.geometry,scale:18000});return {vehicle:selected,found:!!f,details:detail.textContent};}app.actions.register('inspect-live-vehicle',choose);
function bars(root,entries,total){root.replaceChildren();for(const [name,count,color]of entries){const box=el('div',undefined,root);box.style.marginBottom='8px';const label=el('div',undefined,box);Object.assign(label.style,{display:'flex',gap:'6px',alignItems:'center'});const dot=el('span',undefined,label);Object.assign(dot.style,{width:'8px',height:'8px',borderRadius:'50%',background:color,border:'1px solid #3A312833'});el('span',`${name} · ${count}`,label);const track=el('div',undefined,box);Object.assign(track.style,{background:'#E0D2BA66',borderRadius:'4px',marginTop:'4px'});const bar=el('div',undefined,track);Object.assign(bar.style,{height:'6px',background:color,width:`${total?100*count/total:0}%`,borderRadius:'4px'});}}
function renderList(){list.replaceChildren();for(const f of rows){const a=f.attributes,b=el('button',undefined,list);const active=a.vehiclename===selected;Object.assign(b.style,{display:'block',width:'100%',textAlign:'left',minWidth:'0',padding:'10px 14px',marginBottom:'6px',font:'inherit',color:active?'#F8F2E7':'#3A3128',background:active?'#C27A24':'#F8F2E7',border:'1px solid '+(active?'#C27A24':'#E0D2BA'),borderRadius:'24px',cursor:'pointer',boxShadow:'0 1px 2px #3A312808'});b.setAttribute('aria-pressed',String(active));const title=el('div',undefined,b);const dot=el('span',undefined,title);Object.assign(dot.style,{display:'inline-block',width:'8px',height:'8px',borderRadius:'50%',background:typeColor(a.vehicletype),border:'1px solid #3A312833',marginRight:'7px'});el('strong',a.vehiclename,title);const sub=el('div',`${a.vehicletype} · ${a.speed??'—'} · ${age(f)>30?'Stale':Number(a.speed)>0?'Moving':'Stopped'}`,b);Object.assign(sub.style,{fontSize:'12px',color:active?'#F8F2E7':'#8A7C69'});b.onclick=()=>choose({name:a.vehiclename,zoom:true}).catch(e=>app.reportError(e));}}
async function refresh(){if(disposed||busy)return lastResult;busy=true;try{const current=app.map.allLayers.find(l=>l.id===c.layerId);if(!current){status.textContent='Stream unavailable';return {sourcePresent:false};}if(source!==current){handle?.remove();source=current;await source.load();lv=await app.view.whenLayerView(source);if(disposed)return;handle=lv.on('data-received',()=>{received++;lastReceipt=Date.now();times.push(lastReceipt);});}const q=lv.createQuery();q.where='1=1';q.outFields=['vehiclename','vehicletype','speed','heading','time','agency'];q.returnGeometry=true;const [fs,count]=await Promise.all([lv.queryLatestObservations(q,{signal:abort.signal}),lv.queryFeatureCount({where:'1=1'},{signal:abort.signal})]);if(disposed)return;rows=fs.features.sort((a,b)=>String(a.attributes.vehiclename).localeCompare(String(b.attributes.vehiclename)));const n=rows.length,fresh=rows.filter(f=>age(f)<=c.staleSeconds),moving=fresh.filter(f=>Number(f.attributes.speed)>0).length,stopped=fresh.filter(f=>f.attributes.speed!=null&&Number(f.attributes.speed)===0).length,stale=n-fresh.length;const speeds=rows.map(f=>f.attributes.speed).filter(v=>typeof v==='number'&&Number.isFinite(v));const avg=speeds.length?speeds.reduce((a,b)=>a+b,0)/speeds.length:null;values.vehicles.textContent=String(n);values.moving.textContent=String(moving);values.speed.textContent=avg===null?'—':avg.toFixed(1);values.observations.textContent=count.toLocaleString();const now=Date.now();times=times.filter(t=>t>now-60000);const rate=times.length/Math.min(60,Math.max(1,(now-started)/1000));status.textContent=`${lv.connectionStatus}${!source.visible?' · Hidden':lv.suspended?' · Suspended':''}`;receipt.textContent=`${rate.toFixed(1)} updates/s · ${received} received since app opened`;freshness.textContent=`${stale} stale vehicles · ${lastReceipt?'Last receipt '+Math.floor((now-lastReceipt)/1000)+'s ago':'Waiting for new updates'}${lv.connectionError?' · '+lv.connectionError.message:''}`;const groups=new Map();rows.forEach(f=>groups.set(f.attributes.vehicletype,(groups.get(f.attributes.vehicletype)||0)+1));bars(types,[...groups].map(([type,v])=>[type,v,typeColor(type)]),n);if(!n)types.textContent='Waiting for vehicle observations.';bars(activity,[['Moving',moving,c.green],['Stopped',stopped,c.grey],['Stale',stale,c.pickup]],n);const bins=Array(30).fill(0);times.forEach(t=>{const i=29-Math.floor((now-t)/2000);if(i>=0&&i<30)bins[i]++;});const max=Math.max(1,...bins);sparkBars.forEach((b,i)=>{b.style.height=Math.max(1,bins[i]/max*40)+'px';b.title=bins[i]+' updates / 2s';});renderList();details();lastResult={connection:lv.connectionStatus,vehicles:n,moving,stopped,stale,averageSpeed:avg,retainedObservations:count,receivedSinceOpen:received,tracksEnabled:source.trackInfo?.enabled,retention:source.purgeOptions.maxObservations,categoryColors:[...groups].map(([type])=>({type,color:typeColor(type)})),card:'#F8F2E7',primaryText:'#3A3128'};return lastResult;}catch(e){if(!disposed){status.textContent='Live metrics unavailable';freshness.textContent=e.message;app.reportError(e);}return {error:e.message};}finally{busy=false;}}
app.actions.register('refresh-fleet-metrics',refresh);await refresh();timer=setInterval(refresh,c.refreshMs);
}